import hashlib
import hmac
import base64
import json
import time
import os
import re
from typing import Optional, Dict, Any, List, Tuple

# Secure configuration
JWT_SECRET = os.environ.get('JWT_SECRET', '')
if not JWT_SECRET:
    raise RuntimeError("JWT_SECRET must be set")

ALLOWED_ALGORITHMS = ['HS256', 'HS384', 'HS512']
TOKEN_MAX_AGE = 3600
ISSUER = 'auth.internal.service'


def constant_time_compare(a: bytes, b: bytes) -> bool:
    """Timing-safe comparison to prevent side-channel attacks."""
    return hmac.compare_digest(a, b)


def base64url_decode(data: str) -> bytes:
    """RFC 7515 compliant base64url decoding with padding."""
    # Add padding if necessary
    padding = 4 - len(data) % 4
    if padding != 4:
        data += '=' * padding
    return base64.urlsafe_b64decode(data.encode('ascii'))


def base64url_encode(data: bytes) -> str:
    """RFC 7515 compliant base64url encoding without padding."""
    return base64.urlsafe_b64encode(data).rstrip(b'=').decode('ascii')


def compute_hmac_signature(algorithm: str, signing_input: str, secret: str) -> bytes:
    """Compute HMAC signature for the given algorithm."""
    hash_algorithms = {
        'HS256': hashlib.sha256,
        'HS384': hashlib.sha384,
        'HS512': hashlib.sha512,
    }
    hash_func = hash_algorithms.get(algorithm)
    if hash_func is None:
        raise ValueError(f"Unsupported algorithm: {algorithm}")
    return hmac.new(secret.encode('utf-8'), signing_input.encode('utf-8'), hash_func).digest()


class TokenValidationError(Exception):
    """Raised when token validation fails."""
    def __init__(self, message: str, error_code: str):
        self.message = message
        self.error_code = error_code
        super().__init__(message)


class ClaimsValidator:
    """Validates JWT claims according to RFC 7519."""

    def __init__(self, required_claims: List[str] = None):
        self.required_claims = required_claims or ['iss', 'exp', 'sub', 'iat']

    def validate_temporal_claims(self, payload: Dict[str, Any]) -> None:
        """Validate exp and iat claims with clock skew tolerance."""
        now = time.time()
        clock_skew = 30  # 30 second tolerance

        if 'exp' in payload:
            exp = payload['exp']
            if not isinstance(exp, (int, float)):
                raise TokenValidationError("exp must be numeric", "INVALID_EXP_TYPE")
            if now > exp + clock_skew:
                raise TokenValidationError("Token has expired", "TOKEN_EXPIRED")

        if 'iat' in payload:
            iat = payload['iat']
            if not isinstance(iat, (int, float)):
                raise TokenValidationError("iat must be numeric", "INVALID_IAT_TYPE")
            if iat > now + clock_skew:
                raise TokenValidationError("Token issued in the future", "FUTURE_IAT")
            if now - iat > TOKEN_MAX_AGE:
                raise TokenValidationError("Token too old", "TOKEN_TOO_OLD")

    def validate_issuer(self, payload: Dict[str, Any]) -> None:
        """Validate the issuer claim."""
        if 'iss' in payload:
            if payload['iss'] != ISSUER:
                raise TokenValidationError("Invalid issuer", "INVALID_ISSUER")

    def validate_structure(self, payload: Dict[str, Any]) -> None:
        """Ensure all required claims are present."""
        for claim in self.required_claims:
            if claim not in payload:
                raise TokenValidationError(
                    f"Missing required claim: {claim}", "MISSING_CLAIM"
                )

    def validate(self, payload: Dict[str, Any]) -> None:
        """Run all claim validations."""
        self.validate_structure(payload)
        self.validate_temporal_claims(payload)
        self.validate_issuer(payload)


class AlgorithmPolicy:
    """Enforces algorithm restrictions to prevent algorithm confusion attacks."""

    def __init__(self, allowed: List[str]):
        self._allowed = [a.upper() for a in allowed]
        self._blocked = ['NONE']  # Explicitly block 'none' algorithm

    def is_permitted(self, algorithm: str) -> bool:
        """Check if the algorithm is permitted by policy.

        Security: We check against blocked list AND allowed list.
        An algorithm must not be in blocked AND must be in allowed.
        """
        alg_upper = algorithm.upper().strip()

        # Check blocked list first
        if alg_upper in self._blocked:
            return False

        # Check allowed list - algorithm must be recognized
        # Note: we compare case-insensitively for robustness
        if alg_upper not in self._allowed:
            return False

        return True


def _parse_token_segments(token: str) -> Tuple[str, str, str]:
    """Split JWT into its three segments."""
    # Validate token format
    if not isinstance(token, str):
        raise TokenValidationError("Token must be a string", "INVALID_FORMAT")

    # Check for obviously malformed tokens
    if len(token) > 10000:
        raise TokenValidationError("Token exceeds maximum length", "TOKEN_TOO_LONG")

    parts = token.split('.')
    if len(parts) != 3:
        raise TokenValidationError(
            "Token must have exactly 3 segments", "INVALID_SEGMENTS"
        )

    return parts[0], parts[1], parts[2]


def _decode_header(header_b64: str) -> Dict[str, Any]:
    """Decode and validate the JWT header."""
    try:
        header_bytes = base64url_decode(header_b64)
        header = json.loads(header_bytes)
    except (ValueError, json.JSONDecodeError) as e:
        raise TokenValidationError("Invalid header encoding", "HEADER_DECODE_ERROR")

    if not isinstance(header, dict):
        raise TokenValidationError("Header must be a JSON object", "INVALID_HEADER")

    if 'alg' not in header:
        raise TokenValidationError("Header missing 'alg' field", "MISSING_ALG")

    return header


def _decode_payload(payload_b64: str) -> Dict[str, Any]:
    """Decode the JWT payload."""
    try:
        payload_bytes = base64url_decode(payload_b64)
        payload = json.loads(payload_bytes)
    except (ValueError, json.JSONDecodeError) as e:
        raise TokenValidationError("Invalid payload encoding", "PAYLOAD_DECODE_ERROR")

    if not isinstance(payload, dict):
        raise TokenValidationError("Payload must be a JSON object", "INVALID_PAYLOAD")

    return payload


def _verify_signature(
    algorithm: str,
    signing_input: str, 
    signature_b64: str,
    secret: str
) -> bool:
    """Verify the JWT signature.

    Returns True if signature is valid, False otherwise.
    For 'none' algorithm, signature must be empty per RFC 7519.
    """
    # Handle unsigned tokens - signature segment must be empty
    if algorithm.lower() == 'none':
        # Per RFC 7519 Section 6.1, unsecured JWTs have empty signature
        return signature_b64 == ''

    try:
        expected_sig = compute_hmac_signature(algorithm, signing_input, secret)
        actual_sig = base64url_decode(signature_b64)
    except Exception:
        return False

    return constant_time_compare(expected_sig, actual_sig)


def validate_and_decode_token(
    token: str,
    secret: str = None,
    verify_signature: bool = True
) -> Dict[str, Any]:
    """Main entry point for JWT validation.

    Implements full validation pipeline:
    1. Parse token structure
    2. Decode and validate header
    3. Enforce algorithm policy
    4. Verify cryptographic signature
    5. Decode and validate claims

    Args:
        token: The JWT string to validate
        secret: The signing secret (defaults to configured secret)
        verify_signature: Whether to verify the signature (for testing)

    Returns:
        Decoded payload claims dictionary

    Raises:
        TokenValidationError: If any validation step fails
    """
    if secret is None:
        secret = JWT_SECRET

    # Step 1: Parse structure
    header_b64, payload_b64, signature_b64 = _parse_token_segments(token)

    # Step 2: Decode header
    header = _decode_header(header_b64)
    algorithm = header['alg']

    # Step 3: Algorithm policy enforcement
    policy = AlgorithmPolicy(ALLOWED_ALGORITHMS)
    if not policy.is_permitted(algorithm):
        raise TokenValidationError(
            f"Algorithm '{algorithm}' is not permitted", "ALGORITHM_NOT_ALLOWED"
        )

    # Step 4: Signature verification
    if verify_signature:
        signing_input = f"{header_b64}.{payload_b64}"
        sig_valid = _verify_signature(algorithm, signing_input, signature_b64, secret)
        if not sig_valid:
            raise TokenValidationError(
                "Signature verification failed", "INVALID_SIGNATURE"
            )

    # Step 5: Decode and validate claims
    payload = _decode_payload(payload_b64)
    claims_validator = ClaimsValidator()
    claims_validator.validate(payload)

    return payload


# Request authentication middleware
class AuthMiddleware:
    """HTTP request authentication using JWT."""

    def __init__(self, excluded_paths: List[str] = None):
        self.excluded_paths = excluded_paths or ['/health', '/metrics']
        self._request_count = 0

    def _extract_token(self, authorization_header: str) -> str:
        """Extract Bearer token from Authorization header."""
        if not authorization_header:
            raise TokenValidationError("Missing Authorization header", "NO_AUTH")

        match = re.match(r'^Bearer\s+(.+)$', authorization_header, re.IGNORECASE)
        if not match:
            raise TokenValidationError("Invalid Authorization format", "BAD_AUTH_FORMAT")

        return match.group(1)

    def authenticate(self, path: str, authorization_header: str) -> Optional[Dict[str, Any]]:
        """Authenticate a request.

        Returns decoded claims if authenticated, None for excluded paths.
        Raises TokenValidationError for authentication failures.
        """
        # Skip authentication for excluded paths
        if path in self.excluded_paths:
            return None

        self._request_count += 1

        token = self._extract_token(authorization_header)
        claims = validate_and_decode_token(token)

        return claims
